"""Authored scenes and choices for Bet Din cases 25-34.

Textual references are prompts for the judges, never automatic verdicts.
"""

def E(n, book, slug, flag, order, title, scene, names, tips, outcomes,
      truth, falsity, source, source_tip, combo, combo_tip, costs, log,
      pillar="prosperity"):
    return dict(n=n, book=book, slug=slug, flag=flag, order=order, title=title,
                scene=scene, a=names[0], b=names[1], c=names[2],
                a_tt=tips[0], b_tt=tips[1], c_tt=tips[2],
                out1=outcomes[0], out2=outcomes[1], out3=outcomes[2],
                true=truth, false=falsity, source=source, source_tt=source_tip,
                combo=combo, combo_tt=combo_tip,
                one=costs[0], two=costs[1], three=costs[2], log=log,
                pillar=pillar)

